package com.transportlogistics.app.fuel.infrastructure.adapters.out.persistence;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.transportlogistics.app.fuel.application.ports.in.FuelExceptionUseCase;
import com.transportlogistics.app.fuel.application.ports.out.FuelExceptionStore;
import com.transportlogistics.app.fuel.domain.model.FuelExceptionCase;
import com.transportlogistics.app.shared.domain.ConflictException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Component;

import java.time.OffsetDateTime;
import java.util.*;

@Component
class JdbcFuelExceptionStore implements FuelExceptionStore {
    private static final TypeReference<Map<String,String>> MAP = new TypeReference<>() {};
    private final JdbcClient jdbc; private final ObjectMapper json;
    JdbcFuelExceptionStore(JdbcClient jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}

    @Override public FuelExceptionCase insert(FuelExceptionCase v){try{jdbc.sql("""
      insert into fuel_exception_case(id,tenant_id,category,lifecycle,impact,source_type,source_id,source_event_id,summary,safe_metadata,vehicle_id,driver_id,trip_id,card_id,tank_id,occurred_at,review_required,handoff_status,created_by,version,created_at,updated_at)
      values(:id,:t,:category,:lifecycle,:impact,:sourceType,:sourceId,:sourceEventId,:summary,:metadata,:vehicle,:driver,:trip,:card,:tank,:occurred,:review,:handoff,:actor,0,:created,:updated)
      """).params(caseParams(v)).update();return v;}catch(DataIntegrityViolationException ex){throw conflict(ex);}}
    @Override public FuelExceptionCase update(UUID t,UUID id,long version,FuelExceptionCase.Lifecycle lifecycle,boolean review,FuelExceptionCase.HandoffStatus handoff,FuelExceptionCase.Outcome outcome,String reason,UUID resolvedBy,OffsetDateTime now){int n=jdbc.sql("""
      update fuel_exception_case set lifecycle=:lifecycle,review_required=:review,handoff_status=:handoff,resolution_outcome=:outcome,resolution_reason=:reason,resolved_by=:resolved,version=version+1,updated_at=:now
      where tenant_id=:t and id=:id and version=:version
      """).param("lifecycle",lifecycle.name()).param("review",review).param("handoff",handoff.name()).param("outcome",outcome==null?null:outcome.name()).param("reason",reason).param("resolved",resolvedBy).param("now",now).param("t",t).param("id",id).param("version",version).update();if(n!=1)throw conflict(null);return find(t,id).orElseThrow();}
    @Override public Optional<FuelExceptionCase> find(UUID t,UUID id){return jdbc.sql("select * from fuel_exception_case where tenant_id=:t and id=:id").param("t",t).param("id",id).query(this::mapCase).optional();}
    @Override public List<FuelExceptionCase> search(UUID t,FuelExceptionUseCase.Search s){String sort=s.sort()==null?"created_at":switch(s.sort()){case "createdAt"->"created_at";case "occurredAt"->"occurred_at";case "updatedAt"->"updated_at";case "category","lifecycle","impact"->s.sort();default->"created_at";};String direction="asc".equalsIgnoreCase(s.direction())?"asc":"desc";StringBuilder sql=new StringBuilder("select * from fuel_exception_case where tenant_id=:t");Map<String,Object> p=new HashMap<>();p.put("t",t);filter(sql,p,"category",s.category()==null?null:s.category().name());filter(sql,p,"lifecycle",s.lifecycle()==null?null:s.lifecycle().name());filter(sql,p,"source_type",s.sourceType());filter(sql,p,"vehicle_id",s.vehicleId());filter(sql,p,"driver_id",s.driverId());filter(sql,p,"card_id",s.cardId());filter(sql,p,"tank_id",s.tankId());filter(sql,p,"review_required",s.reviewRequired());filter(sql,p,"handoff_status",s.handoffStatus()==null?null:s.handoffStatus().name());if(s.occurredFrom()!=null){sql.append(" and occurred_at>=:from");p.put("from",s.occurredFrom());}if(s.occurredTo()!=null){sql.append(" and occurred_at<=:to");p.put("to",s.occurredTo());}sql.append(" order by ").append(sort).append(' ').append(direction).append(", id ").append(direction).append(" limit :limit offset :offset");p.put("limit",s.limit());p.put("offset",s.page()*s.limit());return jdbc.sql(sql.toString()).params(p).query(this::mapCase).list();}
    @Override public FuelExceptionUseCase.Evidence evidence(UUID t,UUID x,FuelExceptionUseCase.AddEvidence v,UUID actor,OffsetDateTime now){UUID id=UUID.randomUUID();jdbc.sql("insert into fuel_exception_evidence(id,tenant_id,exception_id,evidence_type,source_type,source_id,summary,safe_snapshot,added_by,created_at) values(:id,:t,:x,:type,:st,:sid,:summary,:snap,:actor,:now)").param("id",id).param("t",t).param("x",x).param("type",v.evidenceType()).param("st",v.sourceType()).param("sid",v.sourceId()).param("summary",v.summary()).param("snap",write(v.safeSnapshot())).param("actor",actor).param("now",now).update();return new FuelExceptionUseCase.Evidence(id,v.evidenceType(),v.sourceType(),v.sourceId(),v.summary(),v.safeSnapshot(),actor,now);}
    @Override public FuelExceptionUseCase.Note note(UUID t,UUID x,String note,UUID actor,OffsetDateTime now){UUID id=UUID.randomUUID();jdbc.sql("insert into fuel_exception_note(id,tenant_id,exception_id,note,added_by,created_at) values(:id,:t,:x,:note,:actor,:now)").param("id",id).param("t",t).param("x",x).param("note",note).param("actor",actor).param("now",now).update();return new FuelExceptionUseCase.Note(id,note,actor,now);}
    @Override public FuelExceptionUseCase.Correction correction(UUID t,UUID x,FuelExceptionUseCase.RequestCorrection v,UUID actor,String status,OffsetDateTime now){UUID id=UUID.randomUUID();String command=write(v.ownerCommand());String owner="VEHICLE_READING_CORRECTION".equals(v.correctionType())?"FLEET":"FUEL";String reason=v.ownerCommand().getOrDefault("reason","Correction requested for review");jdbc.sql("insert into fuel_exception_correction(id,tenant_id,exception_id,correction_type,owner_command,changes_financial_fact,status,requested_by,version,created_at,updated_at,owner_module,owner_type,requested_command_type,safe_request_evidence,before_snapshot_hash,request_reason,requested_at,execution_state,idempotency_key) values(:id,:t,:x,:type,:command,:financial,:status,:actor,0,:now,:now,:owner,:type,:type,:command,encode(digest(:command,'sha256'),'hex'),:reason,:now,'NOT_STARTED',:id)").param("id",id).param("t",t).param("x",x).param("type",v.correctionType()).param("command",command).param("financial",v.changesFinancialFact()).param("status",status).param("actor",actor).param("owner",owner).param("reason",reason).param("now",now).update();return correction(t,x,id).orElseThrow();}
    @Override public Optional<FuelExceptionUseCase.Correction> correction(UUID t,UUID x,UUID id){return jdbc.sql("select * from fuel_exception_correction where tenant_id=:t and exception_id=:x and id=:id").param("t",t).param("x",x).param("id",id).query((rs,n)->new FuelExceptionUseCase.Correction(rs.getObject("id",UUID.class),rs.getString("correction_type"),read(rs.getString("owner_command")),rs.getBoolean("changes_financial_fact"),rs.getString("status"),rs.getObject("requested_by",UUID.class),rs.getObject("reviewed_by",UUID.class),rs.getString("review_reason"),rs.getString("owner_result_reference"),rs.getString("failure_code"),rs.getLong("version"),rs.getObject("created_at",OffsetDateTime.class),rs.getObject("updated_at",OffsetDateTime.class))).optional();}
    @Override public FuelExceptionUseCase.Correction reviewCorrection(UUID t,UUID x,UUID id,long version,String status,UUID actor,String reason,OffsetDateTime now){int n=jdbc.sql("update fuel_exception_correction set status=:status,reviewed_by=:actor,review_reason=:reason,version=version+1,updated_at=:now where tenant_id=:t and exception_id=:x and id=:id and version=:version").param("status",status).param("actor",actor).param("reason",reason).param("now",now).param("t",t).param("x",x).param("id",id).param("version",version).update();if(n!=1)throw conflict(null);return correction(t,x,id).orElseThrow();}
    @Override public FuelExceptionUseCase.Correction correctionResult(UUID t,UUID x,UUID id,long version,String status,String reference,String failure,OffsetDateTime now){int n=jdbc.sql("update fuel_exception_correction set status=:status,execution_state=:status,owner_result_reference=:reference,failure_code=:failure,version=version+1,updated_at=:now where tenant_id=:t and exception_id=:x and id=:id and version=:version and execution_state='RUNNING'").param("status",status).param("reference",reference).param("failure",failure).param("now",now).param("t",t).param("x",x).param("id",id).param("version",version).update();if(n!=1)throw conflict(null);return correction(t,x,id).orElseThrow();}
    @Override public Optional<String> successfulCorrectionResult(UUID t,UUID id){return jdbc.sql("select safe_result_reference from fuel_exception_correction_attempt where tenant_id=:t and correction_id=:id and result='SUCCESS' order by attempt_number limit 1").param("t",t).param("id",id).query(String.class).optional();}
    @Override public boolean startCorrectionExecution(UUID t,UUID x,UUID id,long version,OffsetDateTime now){return jdbc.sql("update fuel_exception_correction set execution_state='RUNNING',version=version+1,updated_at=:now where tenant_id=:t and exception_id=:x and id=:id and version=:version and execution_state in ('NOT_STARTED','FAILED')").param("now",now).param("t",t).param("x",x).param("id",id).param("version",version).update()==1;}
    @Override public void correctionAttempt(UUID t,UUID id,UUID key,UUID actor,String result,String reference,String error,OffsetDateTime now){jdbc.sql("with locked as (select id from fuel_exception_correction where tenant_id=:t and id=:id for update), next_attempt as (select coalesce(max(a.attempt_number),0)+1 as number from locked left join fuel_exception_correction_attempt a on a.tenant_id=:t and a.correction_id=:id) insert into fuel_exception_correction_attempt(attempt_id,tenant_id,correction_id,attempt_number,idempotency_key,attempted_at,attempted_by,result,safe_result_reference,safe_error_code,result_hash) select :aid,:t,:id,number,:key,:now,:actor,:result,:reference,:error,case when :reference is null then null else encode(digest(:reference,'sha256'),'hex') end from next_attempt").param("aid",UUID.randomUUID()).param("t",t).param("id",id).param("key",key).param("now",now).param("actor",actor).param("result",result).param("reference",reference).param("error",error).update();}
    @Override public void history(UUID t,UUID x,String action,String from,String to,String detail,UUID actor,OffsetDateTime now){jdbc.sql("insert into fuel_exception_history(id,tenant_id,exception_id,action,from_lifecycle,to_lifecycle,detail,actor_id,created_at) values(:id,:t,:x,:action,:from,:to,:detail,:actor,:now)").param("id",UUID.randomUUID()).param("t",t).param("x",x).param("action",action).param("from",from).param("to",to).param("detail",detail).param("actor",actor).param("now",now).update();}
    @Override public FuelExceptionUseCase.Detail detail(FuelExceptionCase v){UUID t=v.tenantId(),x=v.id();var evidence=jdbc.sql("select * from fuel_exception_evidence where tenant_id=:t and exception_id=:x order by created_at desc,id limit 100").param("t",t).param("x",x).query((rs,n)->new FuelExceptionUseCase.Evidence(rs.getObject("id",UUID.class),rs.getString("evidence_type"),rs.getString("source_type"),rs.getObject("source_id",UUID.class),rs.getString("summary"),read(rs.getString("safe_snapshot")),rs.getObject("added_by",UUID.class),rs.getObject("created_at",OffsetDateTime.class))).list();var notes=jdbc.sql("select * from fuel_exception_note where tenant_id=:t and exception_id=:x order by created_at desc,id limit 100").param("t",t).param("x",x).query((rs,n)->new FuelExceptionUseCase.Note(rs.getObject("id",UUID.class),rs.getString("note"),rs.getObject("added_by",UUID.class),rs.getObject("created_at",OffsetDateTime.class))).list();var corrections=jdbc.sql("select id from fuel_exception_correction where tenant_id=:t and exception_id=:x order by created_at desc,id limit 100").param("t",t).param("x",x).query(UUID.class).list().stream().map(id->correction(t,x,id).orElseThrow()).toList();var history=jdbc.sql("select * from fuel_exception_history where tenant_id=:t and exception_id=:x order by created_at desc,id limit 100").param("t",t).param("x",x).query((rs,n)->new FuelExceptionUseCase.History(rs.getObject("id",UUID.class),rs.getString("action"),rs.getString("from_lifecycle"),rs.getString("to_lifecycle"),rs.getString("detail"),rs.getObject("actor_id",UUID.class),rs.getObject("created_at",OffsetDateTime.class))).list();return new FuelExceptionUseCase.Detail(v,evidence,notes,corrections,history);}
    @Override public UUID handoff(UUID t,UUID x,String reason,OffsetDateTime now){UUID id=UUID.randomUUID();jdbc.sql("insert into fuel_exception_operations_handoff(id,tenant_id,exception_id,handoff_event_id,status,reason,version,created_at,updated_at) values(:id,:t,:x,:event,'PENDING',:reason,0,:now,:now)").param("id",UUID.randomUUID()).param("t",t).param("x",x).param("event",id).param("reason",reason).param("now",now).update();return id;}
    @Override public Optional<UUID> handoffEvent(UUID t,UUID x){return jdbc.sql("select handoff_event_id from fuel_exception_operations_handoff where tenant_id=:t and exception_id=:x").param("t",t).param("x",x).query(UUID.class).optional();}
    @Override public void handoffResult(UUID t,UUID x,String status,String failure,OffsetDateTime now){jdbc.sql("update fuel_exception_operations_handoff set status=:status,failure_code=:failure,attempt_count=attempt_count+1,last_attempt_at=:now,published_at=case when :status='PUBLISHED' then :now else published_at end,version=version+1,updated_at=:now where tenant_id=:t and exception_id=:x").param("status",status).param("failure",failure).param("now",now).param("t",t).param("x",x).update();}
    @Override public boolean sourceExists(UUID t,String type,UUID id){if(type==null||id==null)return false;String table= switch(type){case "FUEL_ISSUE"->"fuel_issue";case "FUEL_PURCHASE"->"fuel_purchase";case "FUEL_PRICE"->"fuel_price";case "BUNKER_TANK","REJECTED_BUNKER_COMMAND"->"bunker_tank";case "FUEL_CARD_INDICATOR"->"fuel_card_transaction_indicator";case "FUEL_PERFORMANCE_INDICATOR"->"fuel_issue";default->null;};if(table==null)return false;return jdbc.sql("select exists(select 1 from "+table+" where tenant_id=:t and id=:id)").param("t",t).param("id",id).query(Boolean.class).single();}
    @SuppressWarnings("PMD.UnusedFormalParameter")
    private FuelExceptionCase mapCase(java.sql.ResultSet rs,int rowNumber)throws java.sql.SQLException{return new FuelExceptionCase(rs.getObject("id",UUID.class),rs.getObject("tenant_id",UUID.class),FuelExceptionCase.Category.valueOf(rs.getString("category")),FuelExceptionCase.Lifecycle.valueOf(rs.getString("lifecycle")),FuelExceptionCase.Impact.valueOf(rs.getString("impact")),rs.getString("source_type"),rs.getObject("source_id",UUID.class),rs.getObject("source_event_id",UUID.class),rs.getString("summary"),read(rs.getString("safe_metadata")),rs.getObject("vehicle_id",UUID.class),rs.getObject("driver_id",UUID.class),rs.getObject("trip_id",UUID.class),rs.getObject("card_id",UUID.class),rs.getObject("tank_id",UUID.class),rs.getObject("occurred_at",OffsetDateTime.class),rs.getBoolean("review_required"),FuelExceptionCase.HandoffStatus.valueOf(rs.getString("handoff_status")),rs.getString("resolution_outcome")==null?null:FuelExceptionCase.Outcome.valueOf(rs.getString("resolution_outcome")),rs.getString("resolution_reason"),rs.getObject("created_by",UUID.class),rs.getObject("resolved_by",UUID.class),rs.getLong("version"),rs.getObject("created_at",OffsetDateTime.class),rs.getObject("updated_at",OffsetDateTime.class));}
    private Map<String,Object> caseParams(FuelExceptionCase v){Map<String,Object> p=new HashMap<>();p.put("id",v.id());p.put("t",v.tenantId());p.put("category",v.category().name());p.put("lifecycle",v.lifecycle().name());p.put("impact",v.impact().name());p.put("sourceType",v.sourceType());p.put("sourceId",v.sourceId());p.put("sourceEventId",v.sourceEventId());p.put("summary",v.summary());p.put("metadata",write(v.safeMetadata()));p.put("vehicle",v.vehicleId());p.put("driver",v.driverId());p.put("trip",v.tripId());p.put("card",v.cardId());p.put("tank",v.tankId());p.put("occurred",v.occurredAt());p.put("review",v.reviewRequired());p.put("handoff",v.handoffStatus().name());p.put("actor",v.createdBy());p.put("created",v.createdAt());p.put("updated",v.updatedAt());return p;}
    private static void filter(StringBuilder sql,Map<String,Object> p,String column,Object value){if(value!=null){String key="p"+p.size();sql.append(" and ").append(column).append("=:").append(key);p.put(key,value);}}
    private String write(Map<String,String> v){try{return json.writeValueAsString(v);}catch(Exception ex){throw new IllegalArgumentException(ex);}}
    private Map<String,String> read(String v){try{return json.readValue(v,MAP);}catch(Exception ex){throw new IllegalStateException(ex);}}
    private static ConflictException conflict(Exception ex){return new ConflictException("FUEL_EXCEPTION_CONFLICT","FUEL_EXCEPTION_CONFLICT",ex);}
}
